            new() { Id = 5, Name = "Dr. Emily Thompson", Title = "Professor of English", Email = "ethompson@university.edu", Bio = "Dr. Thompson is a literary scholar specializing in 19th-century American literature. She has written extensively on the works of Emily Dickinson and Walt Whitman, and directs the university's Creative Writing Program." },
            new() { Id = 6, Name = "Dr. Michael Brown", Title = "Professor of History", Email = "mbrown@university.edu", Bio = "Dr. Brown is a historian of modern Europe with a focus on the World Wars era. He has authored three books and frequently contributes to public history projects. He has been a Fulbright Scholar twice." },
            new() { Id = 7, Name = "Dr. Lisa Nguyen", Title = "Associate Professor of Biology", Email = "lnguyen@university.edu", Bio = "Dr. Nguyen researches molecular genetics and cell biology. Her lab investigates gene expression in cancer cells, and she has secured significant NIH funding for her translational research program." },
            new() { Id = 8, Name = "Dr. David Kim", Title = "Assistant Professor of Mathematics", Email = "dkim@university.edu", Bio = "Dr. Kim works in applied mathematics with a focus on numerical methods and scientific computing. He collaborates closely with engineering departments on computational fluid dynamics research." },
        ];

        _courses =
        [
            // Computer Science
            new() { Id = 1, Code = "CS 101", Title = "Introduction to Computer Science", Description = "A broad introduction to the field of computer science covering fundamental concepts in programming, data representation, algorithms, and computational thinking. Students will complete hands-on projects using Python.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", Location = "Science Hall 201", DepartmentId = 1, InstructorId = 1, IsFeatured = true, MaxEnrollment = 120, CurrentEnrollment = 98 },
            new() { Id = 2, Code = "CS 201", Title = "Data Structures and Algorithms", Description = "Study of core data structures including arrays, linked lists, trees, graphs, and hash tables. Covers algorithm design techniques such as divide and conquer, dynamic programming, and greedy strategies. Includes complexity analysis.", Credits = 4, Schedule = "Tue/Thu 10:30 AM–12:00 PM", Location = "Science Hall 305", DepartmentId = 1, InstructorId = 2, IsFeatured = false, MaxEnrollment = 60, CurrentEnrollment = 55 },
            new() { Id = 3, Code = "CS 310", Title = "Software Engineering", Description = "Principles and practices of software engineering including requirements analysis, system design, testing, version control, and agile methodologies. Students work in teams to deliver a semester-long software project.", Credits = 3, Schedule = "Mon/Wed 2:00–3:20 PM", Location = "Engineering Bldg 110", DepartmentId = 1, InstructorId = 2, IsFeatured = true, MaxEnrollment = 45, CurrentEnrollment = 42 },
            new() { Id = 4, Code = "CS 420", Title = "Artificial Intelligence", Description = "Introduction to the theory and practice of artificial intelligence. Topics include search algorithms, knowledge representation, machine learning fundamentals, neural networks, and ethical considerations in AI.", Credits = 3, Schedule = "Tue/Thu 1:00–2:20 PM", Location = "Science Hall 401", DepartmentId = 1, InstructorId = 1, IsFeatured = true, MaxEnrollment = 50, CurrentEnrollment = 48 },

            // Mathematics
            new() { Id = 5, Code = "MATH 101", Title = "Calculus I", Description = "Covers limits, continuity, differentiation, and integration of single-variable functions. Applications to physics, engineering, and the sciences are emphasized throughout.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", Location = "Math Bldg 100", DepartmentId = 2, InstructorId = 3, IsFeatured = true, MaxEnrollment = 150, CurrentEnrollment = 130 },
