            new() { Id = 7, Code = "MATH 305", Title = "Differential Equations", Description = "Ordinary differential equations including first-order equations, linear systems, series solutions, Laplace transforms, and numerical methods. Applications to modeling real-world phenomena.", Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", Location = "Math Bldg 100", DepartmentId = 2, InstructorId = 8, IsFeatured = false, MaxEnrollment = 60, CurrentEnrollment = 45 },

            // Physics
            new() { Id = 8, Code = "PHYS 101", Title = "General Physics I", Description = "Introductory physics covering mechanics, thermodynamics, and waves. Includes a weekly laboratory section where students perform experiments and write lab reports.", Credits = 4, Schedule = "Mon/Wed/Fri 1:00–1:50 PM + Thu Lab 2:00–4:50 PM", Location = "Physics Bldg 120", DepartmentId = 3, InstructorId = 4, IsFeatured = true, MaxEnrollment = 100, CurrentEnrollment = 88 },
            new() { Id = 9, Code = "PHYS 301", Title = "Quantum Mechanics", Description = "Introduction to quantum theory including wave-particle duality, the Schrödinger equation, angular momentum, spin, and perturbation theory. Requires strong mathematical preparation.", Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:20 PM", Location = "Physics Bldg 310", DepartmentId = 3, InstructorId = 4, IsFeatured = false, MaxEnrollment = 35, CurrentEnrollment = 28 },

            // English
            new() { Id = 10, Code = "ENG 101", Title = "English Composition", Description = "Develops foundational skills in academic writing including thesis development, argumentation, research methods, and revision strategies. Students produce multiple essays across different rhetorical modes.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", Location = "Humanities Hall 102", DepartmentId = 4, InstructorId = 5, IsFeatured = false, MaxEnrollment = 30, CurrentEnrollment = 28 },
            new() { Id = 11, Code = "ENG 250", Title = "American Literature", Description = "Survey of American literature from the colonial period to the present. Readings include works by Hawthorne, Melville, Twain, Dickinson, Fitzgerald, Morrison, and contemporary authors.", Credits = 3, Schedule = "Tue/Thu 2:00–3:20 PM", Location = "Humanities Hall 205", DepartmentId = 4, InstructorId = 5, IsFeatured = true, MaxEnrollment = 35, CurrentEnrollment = 30 },

            // History
            new() { Id = 12, Code = "HIST 101", Title = "World History to 1500", Description = "A global survey of human history from the earliest civilizations through the late medieval period. Examines political, economic, social, and cultural developments across Africa, Asia, Europe, and the Americas.", Credits = 3, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", Location = "Social Sciences 150", DepartmentId = 5, InstructorId = 6, IsFeatured = false, MaxEnrollment = 100, CurrentEnrollment = 75 },
            new() { Id = 13, Code = "HIST 320", Title = "Modern European History", Description = "Examines European history from the French Revolution to the present, including the rise of nationalism, industrialization, the World Wars, the Cold War, and European integration.", Credits = 3, Schedule = "Tue/Thu 10:30 AM–12:00 PM", Location = "Social Sciences 220", DepartmentId = 5, InstructorId = 6, IsFeatured = false, MaxEnrollment = 45, CurrentEnrollment = 38 },

            // Biology
            new() { Id = 14, Code = "BIO 101", Title = "Introduction to Biology", Description = "Broad introduction to biological principles including cell structure, genetics, evolution, ecology, and organismal diversity. Includes a weekly lab component.", Credits = 4, Schedule = "Mon/Wed/Fri 11:00–11:50 AM + Tue Lab 1:00–3:50 PM", Location = "Life Sciences 100", DepartmentId = 6, InstructorId = 7, IsFeatured = true, MaxEnrollment = 120, CurrentEnrollment = 105 },
            new() { Id = 15, Code = "BIO 310", Title = "Molecular Biology", Description = "In-depth study of molecular mechanisms underlying DNA replication, transcription, translation, and gene regulation. Covers modern techniques such as PCR, gel electrophoresis, and CRISPR.", Credits = 3, Schedule = "Tue/Thu 9:00–10:20 AM", Location = "Life Sciences 305", DepartmentId = 6, InstructorId = 7, IsFeatured = false, MaxEnrollment = 40, CurrentEnrollment = 35 },
