@page "/courses"

<PageTitle>Browse Courses</PageTitle>

@inject CatalogService CatalogService

<h1>Browse Courses</h1>

<form method="get" action="courses" class="row g-3 mb-4">
    <div class="col-md-4">
        <label for="search" class="form-label">Search</label>
        <input type="text" class="form-control" id="search" name="searchTerm" value="@SearchTerm" placeholder="Course title, code, or keyword" />
    </div>
    <div class="col-md-3">
        <label for="department" class="form-label">Department</label>
        <select class="form-select" id="department" name="departmentId">
            <option value="">All Departments</option>
            @foreach (var dept in CatalogService.GetDepartments())
            {
                <option value="@dept.Id" selected="@(DepartmentId == dept.Id)">@dept.Name</option>
            }
        </select>
    </div>
    <div class="col-md-2">
        <label for="credits" class="form-label">Credits</label>
        <select class="form-select" id="credits" name="credits">
            <option value="">Any</option>
            <option value="3" selected="@(Credits == 3)">3 credits</option>
            <option value="4" selected="@(Credits == 4)">4 credits</option>
        </select>
    </div>
    <div class="col-md-3 d-flex align-items-end gap-2">
        <button type="submit" class="btn btn-primary">Search</button>
        <a href="courses" class="btn btn-outline-secondary">Clear</a>
    </div>
</form>

@{
    var results = CatalogService.SearchCourses(SearchTerm, DepartmentId, Credits);
}

<p class="text-muted">Showing @results.Count course@(results.Count != 1 ? "s" : "")</p>

@if (results.Count == 0)
{
    <div class="alert alert-info">No courses found matching your criteria. Try adjusting your filters.</div>
}
else
{
    <div class="table-responsive">
        <table class="table table-striped table-hover">
            <thead class="table-dark">
                <tr>
                    <th>Code</th>
                    <th>Title</th>
                    <th>Department</th>
                    <th>Credits</th>
                    <th>Schedule</th>
                    <th>Availability</th>
                    <th></th>
                </tr>
            </thead>
            <tbody>
                @foreach (var course in results)
                {
                    var dept = CatalogService.GetDepartment(course.DepartmentId);
                    var spotsLeft = course.MaxEnrollment - course.CurrentEnrollment;
                    <tr>
                        <td><strong>@course.Code</strong></td>
                        <td>@course.Title</td>
                        <td>@dept?.Name</td>
                        <td>@course.Credits</td>
                        <td>@course.Schedule</td>
                        <td>
                            @if (spotsLeft <= 5)
                            {
                                <span class="badge bg-warning text-dark">@spotsLeft spots left</span>
                            }
                            else
                            {
                                <span class="badge bg-success">@spotsLeft spots left</span>
                            }
                        </td>
                        <td><a href="courses/@course.Id" class="btn btn-sm btn-outline-primary">Details</a></td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
}

@code {
    [SupplyParameterFromQuery] public string? SearchTerm { get; set; }
    [SupplyParameterFromQuery] public int? DepartmentId { get; set; }
    [SupplyParameterFromQuery] public int? Credits { get; set; }
}

@page "/courses/{Id:int}"

<PageTitle>@(course?.Title ?? "Course Not Found")</PageTitle>

@inject CatalogService CatalogService

@if (course is null)
{
    <div class="alert alert-warning">
        <h4>Course Not Found</h4>
        <p>The requested course could not be found. <a href="courses">Browse all courses</a>.</p>
    </div>
}
else
{
    var dept = CatalogService.GetDepartment(course.DepartmentId);
    var instructor = CatalogService.GetInstructor(course.InstructorId);
    var spotsLeft = course.MaxEnrollment - course.CurrentEnrollment;

    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="courses">Courses</a></li>
            <li class="breadcrumb-item"><a href="courses?departmentId=@dept?.Id">@dept?.Name</a></li>
            <li class="breadcrumb-item active" aria-current="page">@course.Code</li>
        </ol>
    </nav>

    <h1>@course.Code — @course.Title</h1>

    <div class="row mt-4">
        <div class="col-lg-8">
            <h3>Description</h3>
            <p>@course.Description</p>

            <h3 class="mt-4">Schedule &amp; Location</h3>
            <table class="table">
                <tbody>
                    <tr><th scope="row" style="width: 150px;">Schedule</th><td>@course.Schedule</td></tr>
                    <tr><th scope="row">Location</th><td>@course.Location</td></tr>
                    <tr><th scope="row">Credits</th><td>@course.Credits</td></tr>
                    <tr>
                        <th scope="row">Availability</th>
                        <td>
                            @course.CurrentEnrollment / @course.MaxEnrollment enrolled
                            @if (spotsLeft <= 5)
                            {
                                <span class="badge bg-warning text-dark ms-2">@spotsLeft spots left</span>
                            }
                            else
                            {
                                <span class="badge bg-success ms-2">@spotsLeft spots left</span>
                            }
                        </td>
                    </tr>
                </tbody>
            </table>

            @if (instructor is not null)
            {
                <h3 class="mt-4">Instructor</h3>
                <div class="card">
                    <div class="card-body">
                        <h5 class="card-title">@instructor.Name</h5>
                        <h6 class="card-subtitle mb-2 text-muted">@instructor.Title</h6>
                        <p class="card-text">@instructor.Bio</p>
                        <p class="card-text"><small class="text-muted">📧 @instructor.Email</small></p>
                    </div>
                </div>
            }
        </div>

        <div class="col-lg-4">
            <div class="card bg-light">
                <div class="card-body text-center">
                    <h5 class="card-title">Interested in this course?</h5>
                    <p class="card-text">Submit an enrollment request to reserve your spot.</p>
                    <a href="enroll?courseId=@course.Id" class="btn btn-primary">Enroll Now</a>
                </div>
            </div>

            @if (dept is not null)
            {
                <div class="card mt-3">
                    <div class="card-body">
                        <h6 class="card-title">@dept.Name Department</h6>
                        <p class="card-text text-muted">@dept.Description</p>
                        <a href="courses?departmentId=@dept.Id" class="btn btn-sm btn-outline-secondary">
                            View all @dept.Code courses
                        </a>
                    </div>
                </div>
            }
        </div>
    </div>
}

@code {
    [Parameter] public int Id { get; set; }

    private Course? course;

    protected override void OnInitialized()
    {
        course = CatalogService.GetCourse(Id);
    }
}

@page "/enroll"

<PageTitle>Enrollment Request</PageTitle>

@inject CatalogService CatalogService

<h1>Enrollment Request</h1>
<p class="lead">Complete the form below to submit an enrollment request. You will receive a confirmation once your request is processed.</p>

<div class="row">
    <div class="col-lg-8">
        <EditForm Model="Model" method="post" OnValidSubmit="HandleSubmit" FormName="enrollment">
            <DataAnnotationsValidator />
            <ValidationSummary class="text-danger" />

            <div class="mb-3">
                <label for="name" class="form-label">Full Name <span class="text-danger">*</span></label>
                <InputText id="name" class="form-control" @bind-Value="Model.Name" />
                <ValidationMessage For="() => Model.Name" class="text-danger" />
            </div>

            <div class="mb-3">
                <label for="studentId" class="form-label">Student ID <span class="text-danger">*</span></label>
                <InputText id="studentId" class="form-control" @bind-Value="Model.StudentId" placeholder="e.g., CS12345" />
                <ValidationMessage For="() => Model.StudentId" class="text-danger" />
            </div>

            <div class="mb-3">
                <label for="email" class="form-label">Email Address</label>
                <InputText id="email" class="form-control" @bind-Value="Model.Email" placeholder="student@university.edu" />
                <ValidationMessage For="() => Model.Email" class="text-danger" />
            </div>

            <div class="mb-3">
                <label for="courseId" class="form-label">Course <span class="text-danger">*</span></label>
                <InputSelect id="courseId" class="form-select" @bind-Value="Model.CourseId">
                    <option value="0">— Select a course —</option>
                    @foreach (var course in CatalogService.GetCourses())
                    {
                        var dept = CatalogService.GetDepartment(course.DepartmentId);
                        <option value="@course.Id">@course.Code — @course.Title (@dept?.Name)</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => Model.CourseId" class="text-danger" />
            </div>

            <div class="mb-3">
                <label for="comments" class="form-label">Comments (optional)</label>
                <InputTextArea id="comments" class="form-control" @bind-Value="Model.Comments" rows="3" />
            </div>

            <button type="submit" class="btn btn-primary">Submit Enrollment Request</button>
        </EditForm>
    </div>
</div>

@code {
    [SupplyParameterFromForm]
    private EnrollmentRequest Model { get; set; } = new();

    [SupplyParameterFromQuery]
    public int? CourseId { get; set; }

    protected override void OnInitialized()
    {
        if (CourseId.HasValue && CourseId.Value > 0)
        {
            Model.CourseId = CourseId.Value;
        }
    }

    private void HandleSubmit()
    {
        CatalogService.SubmitEnrollmentRequest(Model);
        NavigationManager.NavigateTo($"/enroll/confirmation?courseName={Uri.EscapeDataString(GetCourseName())}");
    }

    private string GetCourseName()
    {
        var course = CatalogService.GetCourse(Model.CourseId);
        return course is not null ? $"{course.Code} — {course.Title}" : "Unknown Course";
    }

    [Inject] private NavigationManager NavigationManager { get; set; } = default!;
}

