        <button type="submit" class="btn btn-primary">Search</button>
        <a href="courses" class="btn btn-outline-secondary">Clear</a>
    </div>
</form>

@{
    var results = CatalogService.SearchCourses(SearchTerm, DepartmentId, Credits);
}

<p class="text-muted">Showing @results.Count course@(results.Count != 1 ? "s" : "")</p>

@if (results.Count == 0)
{
    <div class="alert alert-info">No courses found matching your criteria. Try adjusting your filters.</div>
}
else
{
    <div class="table-responsive">
        <table class="table table-striped table-hover">
            <thead class="table-dark">
                <tr>
                    <th>Code</th>
                    <th>Title</th>
                    <th>Department</th>
                    <th>Credits</th>
                    <th>Schedule</th>
                    <th>Availability</th>
                    <th></th>
                </tr>
            </thead>
            <tbody>
                @foreach (var course in results)
                {
                    var dept = CatalogService.GetDepartment(course.DepartmentId);
                    var spotsLeft = course.MaxEnrollment - course.CurrentEnrollment;
                    <tr>
                        <td><strong>@course.Code</strong></td>
                        <td>@course.Title</td>
                        <td>@dept?.Name</td>
                        <td>@course.Credits</td>
                        <td>@course.Schedule</td>
                        <td>
                            @if (spotsLeft <= 5)
                            {
                                <span class="badge bg-warning text-dark">@spotsLeft spots left</span>
                            }
                            else
                            {
                                <span class="badge bg-success">@spotsLeft spots left</span>
                            }
                        </td>
                        <td><a href="courses/@course.Id" class="btn btn-sm btn-outline-primary">Details</a></td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
}

@code {
    [SupplyParameterFromQuery] public string? SearchTerm { get; set; }
    [SupplyParameterFromQuery] public int? DepartmentId { get; set; }
    [SupplyParameterFromQuery] public int? Credits { get; set; }
}

@page "/enroll"

<PageTitle>Enrollment Request</PageTitle>

@inject CatalogService CatalogService

<h1>Enrollment Request</h1>
<p class="lead">Complete the form below to submit an enrollment request. You will receive a confirmation once your request is processed.</p>

<div class="row">
    <div class="col-lg-8">
        <EditForm Model="Model" method="post" OnValidSubmit="HandleSubmit" FormName="enrollment">
            <DataAnnotationsValidator />
            <ValidationSummary class="text-danger" />

            <div class="mb-3">
                <label for="name" class="form-label">Full Name <span class="text-danger">*</span></label>
                <InputText id="name" class="form-control" @bind-Value="Model.Name" />
                <ValidationMessage For="() => Model.Name" class="text-danger" />
            </div>

            <div class="mb-3">
                <label for="studentId" class="form-label">Student ID <span class="text-danger">*</span></label>
                <InputText id="studentId" class="form-control" @bind-Value="Model.StudentId" placeholder="e.g., CS12345" />
                <ValidationMessage For="() => Model.StudentId" class="text-danger" />
            </div>

            <div class="mb-3">
                <label for="email" class="form-label">Email Address</label>
                <InputText id="email" class="form-control" @bind-Value="Model.Email" placeholder="student@university.edu" />
                <ValidationMessage For="() => Model.Email" class="text-danger" />
            </div>

            <div class="mb-3">
                <label for="courseId" class="form-label">Course <span class="text-danger">*</span></label>
                <InputSelect id="courseId" class="form-select" @bind-Value="Model.CourseId">
                    <option value="0">— Select a course —</option>
                    @foreach (var course in CatalogService.GetCourses())
                    {
                        var dept = CatalogService.GetDepartment(course.DepartmentId);
                        <option value="@course.Id">@course.Code — @course.Title (@dept?.Name)</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => Model.CourseId" class="text-danger" />
            </div>

            <div class="mb-3">
                <label for="comments" class="form-label">Comments (optional)</label>
                <InputTextArea id="comments" class="form-control" @bind-Value="Model.Comments" rows="3" />
            </div>

            <button type="submit" class="btn btn-primary">Submit Enrollment Request</button>
        </EditForm>
    </div>
</div>

@code {
    [SupplyParameterFromForm]
    private EnrollmentRequest Model { get; set; } = new();

    [SupplyParameterFromQuery]
    public int? CourseId { get; set; }

    protected override void OnInitialized()
    {
        if (CourseId.HasValue && CourseId.Value > 0)
        {
            Model.CourseId = CourseId.Value;
        }
    }

    private void HandleSubmit()
    {
        CatalogService.SubmitEnrollmentRequest(Model);
        NavigationManager.NavigateTo($"/enroll/confirmation?courseName={Uri.EscapeDataString(GetCourseName())}");
    }

    private string GetCourseName()
    {
        var course = CatalogService.GetCourse(Model.CourseId);
        return course is not null ? $"{course.Code} — {course.Title}" : "Unknown Course";
    }

    [Inject] private NavigationManager NavigationManager { get; set; } = default!;
}

